"""Migrated validation rules from legacy/opportunity_rules.vrl."""

from decimal import Decimal


def _value(row: dict | None, field: str) -> object:
    if row is None:
        return ""
    return row.get(field, "")


def _text(value: object) -> str:
    return "" if value is None else str(value)


def _number(value: object, default: object = 0) -> Decimal:
    """Legacy numeric coercion: empty/missing/None uses the supplied default."""
    if value is None or value == "":
        value = default
    return Decimal(str(value))


def _date_ge(left: object, right: object) -> bool:
    """Legacy date ordering, including the 00000000 no-value sentinel."""
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image in legacy rule-file order."""
    errors: list[dict] = []

    amt = _value(record, "AMT")
    stat_cd = _text(_value(record, "STAT_CD"))
    lost_rsn = _text(_value(record, "LOST_RSN"))
    close_dt = _text(_value(record, "CLOSE_DT"))
    stage_pct = _value(record, "STAGE_PCT")

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not (_number(amt, 0) >= Decimal("0")):
            errors.append(_error("E3001", "Amount negative"))

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and _number(amt, 0) == Decimal("0"):
            errors.append(_error("E3002", "Won opportunity requires amount"))

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "L" and lost_rsn == "":
            errors.append(_error("E3003", "Lost reason required"))

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and close_dt == "00000000":
            errors.append(_error("E3004", "Won opportunity requires close date"))

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _text(_value(old, "STAT_CD"))
        if old_stat_cd == "W" and stat_cd != "W":
            errors.append(_error("E3005", "Cannot reopen a won opportunity"))

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage = _number(stage_pct, 0)
        valid_stage = (
            (stat_cd == "P" and stage == Decimal("10"))
            or (stat_cd == "Q" and stage == Decimal("25"))
            or (stat_cd == "N" and stage == Decimal("60"))
            or (stat_cd == "W" and stage == Decimal("100"))
            or (stat_cd == "L" and stage == Decimal("0"))
        )
        if not valid_stage:
            errors.append(_error("E3006", "Stage percent inconsistent with status"))

    # OPP-007
    if event == "INSERT":
        if not (close_dt == "00000000" or _date_ge(close_dt, today)):
            errors.append(
                _error("E3007", "Close date in past", severity="WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
